package com.kitchendesigner.catalog

/**
 * Parametric catalog expansion (STEP 5) — the generated companion to the
 * hand-written starter [Catalog].
 *
 * The data lives in the Android asset `assets/catalog_expansion.json`,
 * generated by `scripts/generate_catalog.py` (schemaVersion 1, 3,169 SKUs:
 * kitchen cabinets x door styles x finishes, appliances, worktops, floors —
 * plus the whole-home expansion: bathroom cabinets/fixtures, wardrobes,
 * living-room / bedroom / office furniture, and flooring & wall finishes
 * tagged per room type).
 *
 * The JSON schema did not change for the whole-home expansion: room type is
 * NOT a JSON field. It is derived deterministically from kind + cabinetKind
 * + the SKU id structure by [CatalogExpansion.roomTypeOf] (mirrored by
 * `room_of` in the generator): bathroom cabinets use cabinetKind
 * "bath-vanity"/"bath-tall", wardrobes use "wardrobe", furniture/fixture
 * subtypes are the second SKU token (FRN-SOFA-…, FIX-MIRROR-…), and
 * room-tagged flooring/wall finishes carry a room token in the SKU id
 * (FLR-…-BATHROOM, WAL-PAINT-KITCHEN-IVORY). The original untagged floor
 * SKUs derive as [CatalogExpansion.ROOM_ALL].
 *
 * Prices in the expansion are ESTIMATE placeholder prices in USD cents,
 * produced by a deterministic formula in the generator — NOT supplier quotes.
 * Convert for display with the CurrencySpec rates in the BOM module, the
 * same way the starter catalog prices are handled.
 *
 * TODO(runtime parsing): this file deliberately has NO JSON parsing
 * dependency. Parsing the asset at runtime still needs wiring up, either via
 * `org.json` (bundled with Android, no new dependency) reading
 * `context.assets.open("catalog_expansion.json")`, or via
 * kotlinx-serialization with a @Serializable mirror of [ExpansionSku].
 * [ExpansionSku] is intentionally parse-ready for both: flat fields, nullable
 * strings for the optional dimensions, and field names matching the JSON keys
 * one-to-one (sku, kind, cabinetKind, widthMm, heightMm, depthMm, doorStyle,
 * finishId, priceUsdCentsEstimate, region, heatResistant, humidityResistant).
 * The JSON also carries `"supplier": null` per SKU, which has no field here
 * because there are no supplier quotes yet.
 *
 * All functions in [CatalogExpansion] are pure functions over a
 * `List<ExpansionSku>` so they can be unit-tested without Android or the
 * asset file.
 */

/** One SKU from catalog_expansion.json. [kind] is one of
 *  "CABINET" | "APPLIANCE" | "WORKTOP" | "FLOOR" | "FURNITURE" | "FIXTURE" |
 *  "WALL"; [region] is "GLOBAL" | "MENA". [cabinetKind] (e.g. "base",
 *  "wall-lift", "tall-fridge", "bath-vanity", "wardrobe") and [doorStyle]
 *  ("slab" | "shaker" | "handleless" | "glass") are only set for cabinets.
 *  All dimensions are millimetres. For FLOOR/WALL SKUs, heightMm carries the
 *  material thickness (the generator's convention). */
data class ExpansionSku(
    val sku: String,
    val kind: String,
    val cabinetKind: String?,
    val widthMm: Int,
    val heightMm: Int,
    val depthMm: Int,
    val doorStyle: String?,
    val finishId: String,
    val priceUsdCentsEstimate: Long,
    val region: String,
    val heatResistant: Boolean,
    val humidityResistant: Boolean,
)

object CatalogExpansion {
    const val KIND_CABINET = "CABINET"
    const val KIND_APPLIANCE = "APPLIANCE"
    const val KIND_WORKTOP = "WORKTOP"
    const val KIND_FLOOR = "FLOOR"
    const val KIND_FURNITURE = "FURNITURE"
    const val KIND_FIXTURE = "FIXTURE"
    const val KIND_WALL = "WALL"
    const val REGION_GLOBAL = "GLOBAL"
    const val REGION_MENA = "MENA"

    // Room types (derived, not stored in the JSON — see roomTypeOf).
    const val ROOM_KITCHEN = "KITCHEN"
    const val ROOM_BATHROOM = "BATHROOM"
    const val ROOM_LIVING = "LIVING"
    const val ROOM_BEDROOM = "BEDROOM"
    const val ROOM_OFFICE = "OFFICE"
    /** Untagged items suitable for any room (the original floor SKUs). */
    const val ROOM_ALL = "ALL_ROOMS"

    // Category groups (derived — see categoryGroupOf).
    const val GROUP_KITCHEN_CABINETS = "KITCHEN_CABINETS"
    const val GROUP_KITCHEN_APPLIANCES = "KITCHEN_APPLIANCES"
    const val GROUP_KITCHEN_WORKTOPS = "KITCHEN_WORKTOPS"
    const val GROUP_BATHROOM_CABINETS = "BATHROOM_CABINETS"
    const val GROUP_BATHROOM_FIXTURES = "BATHROOM_FIXTURES"
    const val GROUP_BEDROOM_WARDROBES = "BEDROOM_WARDROBES"
    const val GROUP_LIVING_FURNITURE = "LIVING_FURNITURE"
    const val GROUP_BEDROOM_FURNITURE = "BEDROOM_FURNITURE"
    const val GROUP_OFFICE_FURNITURE = "OFFICE_FURNITURE"
    const val GROUP_FLOORING = "FLOORING"
    const val GROUP_WALL_FINISHES = "WALL_FINISHES"

    private val ROOM_TOKENS = setOf(ROOM_KITCHEN, ROOM_BATHROOM, ROOM_LIVING, ROOM_BEDROOM, ROOM_OFFICE)
    private val BATHROOM_CABINET_KINDS = setOf("bath-vanity", "bath-tall")
    private val LIVING_SUBTYPES = setOf("SOFA", "SOFACORNER", "ARMCHAIR", "TVUNIT", "SHELF", "COFFEE", "SIDEBOARD")
    private val BEDROOM_SUBTYPES = setOf("BED", "BEDSIDE", "DRESSER")
    private val OFFICE_SUBTYPES = setOf("DESK", "BOOKCASE", "FILING", "CHAIR")

    /** The subtype token of a generated SKU id: the second "-"-separated
     *  segment (e.g. "SOFA" in FRN-SOFA-2100-S3-FABRIC-GREY, "MIRROR" in
     *  FIX-MIRROR-600-H700-CHROME). Null when the id has no second segment. */
    fun subtypeOf(sku: ExpansionSku): String? = sku.sku.split("-").getOrNull(1)

    /** The room type a SKU belongs to, derived from kind + cabinetKind +
     *  SKU id structure (mirrors `room_of` in scripts/generate_catalog.py).
     *  Unknown furniture subtypes and unrecognised kinds derive as
     *  [ROOM_ALL] rather than throwing, so hand-written SKUs stay usable. */
    fun roomTypeOf(sku: ExpansionSku): String = when (sku.kind) {
        KIND_CABINET -> when (sku.cabinetKind) {
            in BATHROOM_CABINET_KINDS -> ROOM_BATHROOM
            "wardrobe" -> ROOM_BEDROOM
            else -> ROOM_KITCHEN
        }
        KIND_APPLIANCE, KIND_WORKTOP -> ROOM_KITCHEN
        KIND_FIXTURE -> ROOM_BATHROOM
        KIND_FURNITURE -> when (subtypeOf(sku)) {
            in LIVING_SUBTYPES -> ROOM_LIVING
            in BEDROOM_SUBTYPES -> ROOM_BEDROOM
            in OFFICE_SUBTYPES -> ROOM_OFFICE
            else -> ROOM_ALL
        }
        KIND_FLOOR -> sku.sku.substringAfterLast("-").takeIf { it in ROOM_TOKENS } ?: ROOM_ALL
        KIND_WALL -> sku.sku.split("-").getOrNull(2)?.takeIf { it in ROOM_TOKENS } ?: ROOM_ALL
        else -> ROOM_ALL
    }

    /** The category group a SKU belongs to (e.g. BATHROOM_FIXTURES,
     *  BEDROOM_WARDROBES, WALL_FINISHES), derived like [roomTypeOf]. */
    fun categoryGroupOf(sku: ExpansionSku): String = when (sku.kind) {
        KIND_CABINET -> when {
            sku.cabinetKind in BATHROOM_CABINET_KINDS -> GROUP_BATHROOM_CABINETS
            sku.cabinetKind == "wardrobe" -> GROUP_BEDROOM_WARDROBES
            else -> GROUP_KITCHEN_CABINETS
        }
        KIND_APPLIANCE -> GROUP_KITCHEN_APPLIANCES
        KIND_WORKTOP -> GROUP_KITCHEN_WORKTOPS
        KIND_FIXTURE -> GROUP_BATHROOM_FIXTURES
        KIND_FURNITURE -> when (roomTypeOf(sku)) {
            ROOM_LIVING -> GROUP_LIVING_FURNITURE
            ROOM_BEDROOM -> GROUP_BEDROOM_FURNITURE
            ROOM_OFFICE -> GROUP_OFFICE_FURNITURE
            else -> "FURNITURE"
        }
        KIND_FLOOR -> GROUP_FLOORING
        KIND_WALL -> GROUP_WALL_FINISHES
        else -> "OTHER"
    }

    /** SKUs belonging to [roomType] (one of the ROOM_* constants).
     *  [ROOM_ALL] items (untagged flooring) are included for every specific
     *  room, since they are suitable anywhere; querying [ROOM_ALL] itself
     *  returns only the untagged items. */
    fun filterByRoomType(skus: List<ExpansionSku>, roomType: String): List<ExpansionSku> =
        skus.filter { val r = roomTypeOf(it); r == roomType || (roomType != ROOM_ALL && r == ROOM_ALL) }

    /** SKU counts grouped by derived room type (exact derivation; ROOM_ALL
     *  items are counted once, under ROOM_ALL — unlike [filterByRoomType],
     *  which also surfaces them per room). */
    fun countByRoomType(skus: List<ExpansionSku>): Map<String, Int> =
        skus.groupingBy { roomTypeOf(it) }.eachCount()

    /** SKUs in one category group (see the GROUP_* constants). */
    fun filterByCategoryGroup(skus: List<ExpansionSku>, group: String): List<ExpansionSku> =
        skus.filter { categoryGroupOf(it) == group }

    /** SKU counts grouped by category group. */
    fun countByCategoryGroup(skus: List<ExpansionSku>): Map<String, Int> =
        skus.groupingBy { categoryGroupOf(it) }.eachCount()

    /** Furniture/fixtures of one subtype (e.g. "SOFA", "MIRROR", "DESK"). */
    fun filterBySubtype(skus: List<ExpansionSku>, subtype: String): List<ExpansionSku> =
        skus.filter { subtypeOf(it) == subtype }

    /** SKU counts grouped by top-level kind ("CABINET", "APPLIANCE", ...). */
    fun countByKind(skus: List<ExpansionSku>): Map<String, Int> =
        skus.groupingBy { it.kind }.eachCount()

    /** SKU counts grouped by cabinet kind ("base", "wall", ...);
     *  non-cabinet SKUs are excluded. */
    fun countByCabinetKind(skus: List<ExpansionSku>): Map<String, Int> =
        skus.filter { it.cabinetKind != null }
            .groupingBy { it.cabinetKind!! }.eachCount()

    /** Find one SKU by its exact id, or null when absent. */
    fun lookup(skus: List<ExpansionSku>, sku: String): ExpansionSku? =
        skus.firstOrNull { it.sku == sku }

    /** SKUs tagged for [region] ("GLOBAL" or "MENA"). */
    fun filterByRegion(skus: List<ExpansionSku>, region: String): List<ExpansionSku> =
        skus.filter { it.region == region }

    /** SKUs of one top-level [kind] (see the KIND_* constants). */
    fun filterByKind(skus: List<ExpansionSku>, kind: String): List<ExpansionSku> =
        skus.filter { it.kind == kind }

    /** Cabinets of one [cabinetKind] (e.g. "base", "tall-fridge"). */
    fun filterByCabinetKind(skus: List<ExpansionSku>, cabinetKind: String): List<ExpansionSku> =
        skus.filter { it.cabinetKind == cabinetKind }

    /** Cabinets of one [cabinetKind] and exact [widthMm] — the parametric
     *  lookup a layout generator needs when filling a run. */
    fun filterByWidth(skus: List<ExpansionSku>, cabinetKind: String, widthMm: Int): List<ExpansionSku> =
        skus.filter { it.cabinetKind == cabinetKind && it.widthMm == widthMm }

    /** SKUs whose finish/material carries the given [finishId]. */
    fun filterByFinish(skus: List<ExpansionSku>, finishId: String): List<ExpansionSku> =
        skus.filter { it.finishId == finishId }

    /** MENA-tagged SKUs that are also heat-resistant — the safe shortlist for
     *  hot-climate kitchens (e.g. next to a hob, or in unconditioned spaces). */
    fun menaHeatSafe(skus: List<ExpansionSku>): List<ExpansionSku> =
        skus.filter { it.region == REGION_MENA && it.heatResistant }

    /** MENA-tagged SKUs that are also humidity-resistant (coastal / humid
     *  kitchens, sink runs). */
    fun menaHumiditySafe(skus: List<ExpansionSku>): List<ExpansionSku> =
        skus.filter { it.region == REGION_MENA && it.humidityResistant }

    /** SKUs resistant to both heat and humidity, in any region. */
    fun heatAndHumiditySafe(skus: List<ExpansionSku>): List<ExpansionSku> =
        skus.filter { it.heatResistant && it.humidityResistant }
}
